import openpyxl

wb = openpyxl.load_workbook('protein_expression.xlsx')
task = wb['Task']

# Check yellow cells in stats section
print("=== Yellow cells in rows 24-27 ===")
for row in range(24, 28):
    yellow_cols = []
    for col in range(1, 13):
        cell = task.cell(row=row, column=col)
        if cell.fill and cell.fill.start_color and cell.fill.start_color.rgb == '00FFFF00':
            yellow_cols.append(openpyxl.utils.get_column_letter(col))
    print(f"  Row {row}: yellow in cols {', '.join(yellow_cols)}")

# Check yellow cells in fold change section
print("\n=== Yellow cells in rows 32-41 ===")
for row in range(32, 42):
    yellow_cols = []
    for col in range(1, 13):
        cell = task.cell(row=row, column=col)
        if cell.fill and cell.fill.start_color and cell.fill.start_color.rgb == '00FFFF00':
            yellow_cols.append(openpyxl.utils.get_column_letter(col))
    if yellow_cols:
        print(f"  Row {row}: yellow in cols {', '.join(yellow_cols)}")

# Check yellow cells in data section
print("\n=== Yellow cells in rows 11-20 ===")
